import { buildError, buildHelp, getProgramName } from "./text.mjs";

const KNOWN_LONG_OPTIONS = ["help", "a", "b", "c"];
const REQUIRED_OPTIONS = ["a", "b", "c"];

export class CliExit extends Error {
  constructor(exitCode, text, stream) {
    super(text);
    this.name = "CliExit";
    this.exitCode = exitCode;
    this.text = text;
    this.stream = stream;
  }
}

function createCliError(programName, message) {
  return new CliExit(2, buildError(programName, message), "stderr");
}

function splitLongOption(token) {
  const body = token.slice(2);
  const equalIndex = body.indexOf("=");

  if (equalIndex === -1) {
    return { name: body, attachedValue: null };
  }

  return {
    name: body.slice(0, equalIndex),
    attachedValue: body.slice(equalIndex + 1),
  };
}

function resolveLongOption(name) {
  const matches = KNOWN_LONG_OPTIONS.filter((option) => option.startsWith(name));
  if (matches.length !== 1) {
    return null;
  }

  return matches[0];
}

function isNegativeNumberLikeToken(token) {
  return /^-\d+$/.test(token) || /^-\d*\.\d+$/.test(token);
}

function isIntegerLiteral(token) {
  return /^[+-]?\d+$/.test(token);
}

function parseBigInteger(token) {
  const sign = token.startsWith("-") ? -1n : 1n;
  const digits = token[0] === "+" || token[0] === "-" ? token.slice(1) : token;
  let value = 0n;

  for (const digit of digits) {
    value = (value * 10n) + BigInt(digit);
  }

  return sign * value;
}

function nextTokenCanBeConsumedAsValue(token) {
  if (token === undefined || token === "--") {
    return false;
  }

  if (!token.startsWith("-")) {
    return true;
  }

  return isNegativeNumberLikeToken(token);
}

function collectUnknownToken(argv, index, extras) {
  extras.push(argv[index]);

  if (
    index + 1 < argv.length &&
    !argv[index].includes("=") &&
    !argv[index + 1].startsWith("-")
  ) {
    extras.push(argv[index + 1]);
    return index + 1;
  }

  return index;
}

export function parseCommandLine(argv, scriptPath) {
  const programName = getProgramName(scriptPath);
  const values = new Map();
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "-h") {
      throw new CliExit(0, buildHelp(programName), "stdout");
    }

    if (token.startsWith("-h=")) {
      throw createCliError(
        programName,
        `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
      );
    }

    if (token === "--") {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token.startsWith("--")) {
      const { name, attachedValue } = splitLongOption(token);
      const resolved = resolveLongOption(name);

      if (resolved === "help") {
        if (attachedValue !== null) {
          throw createCliError(
            programName,
            `argument -h/--help: ignored explicit argument '${attachedValue}'`,
          );
        }

        throw new CliExit(0, buildHelp(programName), "stdout");
      }

      if (resolved === null) {
        index = collectUnknownToken(argv, index, extras);
        continue;
      }

      let rawValue = attachedValue;
      if (rawValue === null) {
        const candidate = argv[index + 1];
        if (!nextTokenCanBeConsumedAsValue(candidate)) {
          throw createCliError(programName, `argument --${resolved}: expected one argument`);
        }

        rawValue = candidate;
        index += 1;
      }

      if (!isIntegerLiteral(rawValue)) {
        throw createCliError(
          programName,
          `argument --${resolved}: invalid int value: '${rawValue}'`,
        );
      }

      values.set(resolved, parseBigInteger(rawValue));
      continue;
    }

    if (token.startsWith("-")) {
      index = collectUnknownToken(argv, index, extras);
      continue;
    }

    extras.push(token);
  }

  const missing = REQUIRED_OPTIONS.filter((name) => !values.has(name));
  if (missing.length > 0) {
    throw createCliError(
      programName,
      `the following arguments are required: ${missing.map((name) => `--${name}`).join(", ")}`,
    );
  }

  if (extras.length > 0) {
    throw createCliError(programName, `unrecognized arguments: ${extras.join(" ")}`);
  }

