  const normalized = String(scriptPath).replace(/\\/g, "/");
  const pieces = normalized.split("/");
  return pieces[pieces.length - 1] || normalized;
}

export function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C`;
}

