import { scheduleNextRun } from "./timing.mjs";

function lambdaLabel(jobFunc) {
  return jobFunc && jobFunc.name ? jobFunc.name : "<lambda>";
}

export class Job {
  constructor(interval, registerJob) {
    this.interval = interval;
    this.unit = null;
    this.startDay = null;
    this.jobFunc = null;
    this.jobFuncLabel = null;
    this.args = [];
    this.kwargs = {};
    this.nextRun = null;
    this.registerJob = registerJob;
  }

  get seconds() {
    this.unit = "seconds";
    return this;
  }

  get minutes() {
    this.unit = "minutes";
    return this;
  }

  get hours() {
    this.unit = "hours";
    return this;
  }

  get day() {
    this.unit = "days";
    return this;
  }

  get week() {
    this.unit = "weeks";
    return this;
  }

  get monday() {
    return this.onWeekday("monday");
  }

  get tuesday() {
    return this.onWeekday("tuesday");
  }

  get wednesday() {
    return this.onWeekday("wednesday");
  }

  get thursday() {
    return this.onWeekday("thursday");
  }

  get friday() {
    return this.onWeekday("friday");
  }

  get saturday() {
    return this.onWeekday("saturday");
  }

  get sunday() {
    return this.onWeekday("sunday");
  }

  onWeekday(dayName) {
    this.unit = "weeks";
    this.startDay = dayName;
    return this;
  }

  do(jobFunc, ...args) {
    this.jobFunc = jobFunc;
    this.jobFuncLabel = lambdaLabel(jobFunc);
    this.args = args;
    scheduleNextRun(this);
    this.registerJob(this);
    return this;
  }

  toString() {
    return `Job(interval=${this.interval.toString()}, unit=${this.unit}, do=${this.jobFuncLabel}, args=(), kwargs={})`;
  }
}

