import { parseCommandLine, CliExit } from "./lib/cli/parser.mjs";
import { every, getJobs } from "./lib/schedule/index.mjs";

function writeText(streamName, text) {
  const stream = streamName === "stderr" ? process.stderr : process.stdout;
  stream.write(text);
}

function main() {
  const args = parseCommandLine(process.argv.slice(2), process.argv[1]);

  const job1 = every(args.a).seconds.do(() => undefined);
  console.log(String(job1.interval));

  const job2 = every(args.b).minutes.do(() => undefined);
  console.log(String(job2.interval));

  const job3 = every(args.c).hours.do(() => undefined);
  console.log(String(job3.interval));

  const job4 = every().day.do(() => undefined);
  console.log(String(job4));

  const job5 = every().week.do(() => undefined);
  console.log(String(job5));

  const job6 = every().monday.do(() => undefined);
  console.log(String(job6));

  const job7 = every().tuesday.do(() => undefined);
  console.log(String(job7));

  const job8 = every().wednesday.do(() => undefined);
  console.log(String(job8));

  const job9 = every().thursday.do(() => undefined);
  console.log(String(job9));

  const job10 = every().friday.do(() => undefined);
  console.log(String(job10));

  const job11 = every().saturday.do(() => undefined);
  console.log(String(job11));

  const job12 = every().sunday.do(() => undefined);
  console.log(String(job12));

  const allJobs = getJobs();
  console.log(String(allJobs.length));
}

try {
  main();
} catch (error) {
  if (error instanceof CliExit) {
    writeText(error.stream, error.text);
    process.exit(error.exitCode);
