  seconds: 1_000n,
  minutes: 60_000n,
  hours: 3_600_000n,
  days: 86_400_000n,
  weeks: 604_800_000n,
};

const FAST_FAILURE_THRESHOLD = 50_000_000n;

export class ScheduleOverflowError extends Error {
  constructor(message) {
    super(message);
    this.name = "ScheduleOverflowError";
  }
}

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysBeforeYear(year) {
  const previousYear = BigInt(year - 1);
  return (previousYear * 365n) + (previousYear / 4n) - (previousYear / 100n) + (previousYear / 400n);
}

function daysBeforeMonth(year, month) {
  const commonYearOffsets = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
  let offset = commonYearOffsets[month - 1];
  if (month > 2 && isLeapYear(year)) {
    offset += 1;
  }

  return BigInt(offset);
}

function localTimeParts() {
  const now = new Date();
  return {
    year: now.getFullYear(),
    month: now.getMonth() + 1,
    day: now.getDate(),
    hour: now.getHours(),
    minute: now.getMinutes(),
    second: now.getSeconds(),
    millisecond: now.getMilliseconds(),
    epochMilliseconds: BigInt(now.getTime()),
  };
}

function unitsSinceYearOne(parts, unit) {
  const dayIndex =
    daysBeforeYear(parts.year) +
    daysBeforeMonth(parts.year, parts.month) +
    BigInt(parts.day - 1);
  const hourIndex = (dayIndex * 24n) + BigInt(parts.hour);
  const minuteIndex = (hourIndex * 60n) + BigInt(parts.minute);
  const secondIndex = (minuteIndex * 60n) + BigInt(parts.second);

  switch (unit) {
    case "weeks":
      return dayIndex / 7n;
    case "days":
      return dayIndex;
    case "hours":
      return hourIndex;
    case "minutes":
      return minuteIndex;
    case "seconds":
      return secondIndex;
    default:
      return 0n;
  }
}

function blockForever() {
  // Mirror the Python library's non-terminating behavior for zero or extremely
  // small negative intervals without depending on an external scheduler package.
  while (true) {
    // Intentionally empty.
  }
}

export function scheduleNextRun(job) {
  const unitMs = UNIT_MS[job.unit];
  if (unitMs === undefined) {
    job.nextRun = null;
    return;
  }

  if (job.interval === 0n) {
    blockForever();
  }

  if (job.interval < 0n) {
    const parts = localTimeParts();
    const stepsToUnderflow = (unitsSinceYearOne(parts, job.unit) / (-job.interval)) + 2n;

    if (stepsToUnderflow > FAST_FAILURE_THRESHOLD) {
      blockForever();
    }

    let cursor = 0n;
    for (let index = 0n; index < stepsToUnderflow; index += 1n) {
      cursor += 1n;
    }

    if (cursor >= 0n) {
      throw new ScheduleOverflowError("date value out of range");
    }
  }

  const parts = localTimeParts();
  const nextEpochMs = parts.epochMilliseconds + (job.interval * unitMs);
  const numericEpochMs = Number(nextEpochMs);

  job.nextRun = Number.isFinite(numericEpochMs) ? new Date(numericEpochMs) : null;
}

