function normalizeInterval(interval) {
  if (typeof interval === "bigint") {
    return interval;
  }

  if (typeof interval === "number") {
    return BigInt(interval);
  }

  return BigInt(interval);
}

export function every(interval = 1n) {
  return new Job(normalizeInterval(interval), registerJob);
}

