const KNOWN_LONG_OPTIONS = ["help", "a", "b", "c"];
const REQUIRED_OPTIONS = ["a", "b", "c"];

export class CliExit extends Error {
  constructor(exitCode, text, stream) {
    super(text);
    this.name = "CliExit";
    this.exitCode = exitCode;
    this.text = text;
    this.stream = stream;
  }
}

function createCliError(programName, message) {
  return new CliExit(2, buildError(programName, message), "stderr");
}

function splitLongOption(token) {
  const body = token.slice(2);
  const equalIndex = body.indexOf("=");

  if (equalIndex === -1) {
    return { name: body, attachedValue: null };
  }

  return {
    name: body.slice(0, equalIndex),
    attachedValue: body.slice(equalIndex + 1),
  };
}

function resolveLongOption(name) {
  const matches = KNOWN_LONG_OPTIONS.filter((option) => option.startsWith(name));
  if (matches.length !== 1) {
    return null;
  }

  return matches[0];
}

function isNegativeNumberLikeToken(token) {
  return /^-\d+$/.test(token) || /^-\d*\.\d+$/.test(token);
}

function isIntegerLiteral(token) {
  return /^[+-]?\d+$/.test(token);
}

function parseBigInteger(token) {
  const sign = token.startsWith("-") ? -1n : 1n;
  const digits = token[0] === "+" || token[0] === "-" ? token.slice(1) : token;
  let value = 0n;

  for (const digit of digits) {
    value = (value * 10n) + BigInt(digit);
  }

  return sign * value;
