  if (token === undefined || token === "--") {
    return false;
  }

  if (!token.startsWith("-")) {
    return true;
  }

  return isNegativeNumberLikeToken(token);
}

function collectUnknownToken(argv, index, extras) {
  extras.push(argv[index]);

  if (
    index + 1 < argv.length &&
    !argv[index].includes("=") &&
    !argv[index + 1].startsWith("-")
  ) {
    extras.push(argv[index + 1]);
    return index + 1;
  }

  return index;
}

export function parseCommandLine(argv, scriptPath) {
  const programName = getProgramName(scriptPath);
  const values = new Map();
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "-h") {
      throw new CliExit(0, buildHelp(programName), "stdout");
    }

    if (token.startsWith("-h=")) {
      throw createCliError(
        programName,
        `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
      );
    }

    if (token === "--") {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token.startsWith("--")) {
      const { name, attachedValue } = splitLongOption(token);
      const resolved = resolveLongOption(name);

      if (resolved === "help") {
        if (attachedValue !== null) {
